def transform(grid):
    """Extend each numbered cross's center color across its row and column.

    Existing non-background cells (including the 3-colored cross arms) are
    preserved. Where colored row and column rays cross on background, the
    vertical ray takes precedence. A 3-armed empty cross marks a gap in every
    horizontal ray at its center column.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    horizontal = {r: color for r, c, color in centers}
    vertical = {c: color for r, c, color in centers}
    gaps = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and
                grid[r - 1][c] == grid[r + 1][c] ==
                grid[r][c - 1] == grid[r][c + 1] == 3):
                gaps.add(c)
    # Rays extend from each center until the first original non-background
    # cell (another cross arm/center) blocks them. Paint horizontal rays first,
    # then vertical rays, so vertical colors resolve crossings.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            while 0 <= x < w and grid[r][x] == 0:
                if x not in gaps:
                    out[r][x] = color
                x += dc
        for dr in (-1, 1):
            y = r + dr
            while 0 <= y < h and grid[y][c] == 0:
                out[y][c] = color
                y += dr
    return out

